lessons.body:
UIKit uses three complementary patterns for event handling and communication between objects.

**Responder Chain**
Every `UIResponder` (views, view controllers, the app itself) participates in a chain. When a touch event fires, UIKit hit-tests to find the deepest view that was tapped — the *first responder*. If that view doesn't handle the event, it travels *up* through superviews, then the view controller, then the window, then UIApplication.

**Target-Action**
`UIControl` subclasses (buttons, sliders, etc.) use target-action to decouple event source from handler. You register a target object and selector; when the event fires, UIKit sends the message.

**Delegation**
Delegation lets one object hand off responsibilities to another via a protocol. The delegating object holds a `weak` reference to its delegate to **prevent retain cycles**. Delegate protocols are typically adopted through a **class extension** — e.g. `extension ProfileViewController: CardViewDelegate { ... }` — which keeps the delegate methods grouped separately from the view controller's own logic.

```swift
// Target-action
let button = UIButton(type: .system)
button.addTarget(self, action: #selector(handleTap), for: .touchUpInside)

@objc private func handleTap() {
    print("Button tapped")
}

// Delegation
protocol CardViewDelegate: AnyObject {
    func cardViewDidDismiss(_ cardView: CardView)
}

class CardView: UIView {
    weak var delegate: CardViewDelegate?

    private func dismiss() {
        delegate?.cardViewDidDismiss(self)
    }
}
```

codeSnippet.code:
class LoginViewController: UIViewController {
    private let loginButton = UIButton(type: .system)

    override func viewDidLoad() {
        super.viewDidLoad()
        loginButton.addTarget(self, action: #selector(handleLogin), for: .touchUpInside)
    }

    @objc private func handleLogin() {
        print("logging in")
    }
}

class AvatarCell: UITableViewCell {
    @IBOutlet private var avatarView: UIImageView!

    func configure(with url: URL) {
        avatarView.image = placeholder
        imageLoader.load(url) { image in
            self.avatarView.image = image
        }
    }
}

var snapshot = dataSource.snapshot()
snapshot.deleteItems([archivedMessage])
dataSource.apply(snapshot, animatingDifferences: true)

class DownloadViewController: UIViewController {
    func startDownload() {
        networkService.fetchLargeFile { [weak self] result in
            self?.updateProgress(with: result)
        }
    }
}

class PollingViewController: UIViewController {
    private var timer: Timer?

    override func viewDidLoad() {
        super.viewDidLoad()
        timer = Timer.scheduledTimer(withTimeInterval: 5, repeats: true) { _ in
            self.refresh()
        }
    }
}

struct ActivityIndicatorView: UIViewRepresentable {
    func makeUIView(context: Context) -> UIActivityIndicatorView {
        let view = UIActivityIndicatorView(style: .medium)
        view.startAnimating()
        return view
    }

    func updateUIView(_ uiView: UIActivityIndicatorView, context: Context) {
    }
}

func updateBadgeCount(_ count: Int) {
    badgeLabel.text = "\(count)"
    setNeedsLayout()
    layoutIfNeeded()
}

